<?php
require_once __DIR__.'/production.php';
try {
 $today=new DateTimeImmutable('today');$start=validDate(textfield($_GET,'start',10)?:$today->modify('monday this week')->format('Y-m-d'));$end=validDate(textfield($_GET,'end',10)?:$today->modify('sunday next week')->format('Y-m-d'));
 if($start>$end)throw new InvalidArgumentException('시작 날짜는 마지막 날짜보다 앞서야 합니다.');
 $ids=productionSelection($_GET['order_ids']??[]);$retail=$_GET['retail']??[];if(!is_array($retail))throw new InvalidArgumentException('소매점 추가량을 확인해 주세요.');
 $orders=query('SELECT o.* FROM orders o WHERE o.cancelled=0 AND o.delivery_date BETWEEN ? AND ? AND EXISTS (SELECT 1 FROM order_items i WHERE i.order_id=o.id AND i.quantity-i.cancelled_quantity-i.delivered_quantity>0) ORDER BY o.delivery_date,o.id LIMIT 200',[$start,$end])->fetchAll();
 $items=[];$picked=[];
 if($ids){$marks=implode(',',array_fill(0,count($ids),'?'));$picked=query('SELECT * FROM orders WHERE id IN ('.$marks.') AND cancelled=0 AND delivery_date BETWEEN ? AND ? ORDER BY delivery_date,id',[...$ids,$start,$end])->fetchAll();if(count($picked)!==count($ids))throw new InvalidArgumentException('선택 주문의 날짜나 취소 상태가 바뀌었습니다. 다시 선택해 주세요.');$items=query('SELECT i.* FROM order_items i JOIN orders o ON o.id=i.order_id WHERE o.id IN ('.$marks.') AND o.cancelled=0',$ids)->fetchAll();}
 $result=productionRequirements($items,$retail);$calculated=isset($_GET['calculate']);
} catch(InvalidArgumentException $e){echo '<div class="alert error">'.e($e->getMessage()).'</div><a href="/?page=production">생산 계획으로 돌아가기</a>';return;}
?>
<section class="panel"><h2>어떤 주문을 생산할까요?</h2><p>전달 예정일로 주문을 찾고 체크한 뒤 ‘재료 소요량 계산’을 누르세요. 취소·이미 전달한 수량은 제외하고 남은 수량을 계산합니다.</p><p class="hint">생산 완료 기록 기능은 아직 없습니다. 이 화면은 재료 계산용이며 주문·입금 상태를 변경하지 않습니다.</p>
<form method="get" class="inline-form"><input type="hidden" name="page" value="production"><label>예정일 시작<input type="date" name="start" value="<?=e($start)?>" required></label><label>예정일 끝<input type="date" name="end" value="<?=e($end)?>" required></label><button class="button secondary">주문 찾기</button></form></section>
<form method="get" id="production-form"><input type="hidden" name="page" value="production"><input type="hidden" name="start" value="<?=e($start)?>"><input type="hidden" name="end" value="<?=e($end)?>"><input type="hidden" name="calculate" value="1">
<section class="panel"><div class="section-title"><h2>선택할 주문 <?=count($orders)?>건</h2><button type="button" class="button secondary" id="production-select-all">전체 선택 / 해제</button></div><p class="hint">최대 200건을 표시합니다. 주문이 많으면 날짜 범위를 줄여 주세요.</p><div class="table-wrap"><table><thead><tr><th>선택</th><th>주문</th><th>고객</th><th>예정일</th><th>받는 방법</th><th>대기 제품</th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td><input type="checkbox" name="order_ids[]" value="<?=$o['id']?>" aria-label="주문 <?=$o['id']?> 선택" <?=in_array($o['id'],$ids,true)?'checked':''?>></td><td><a href="/?page=order&id=<?=$o['id']?>">#<?=$o['id']?></a></td><td><?=e($o['customer_name'])?></td><td><?=e($o['delivery_date'])?></td><td><?=e(fulfillmentLabel($o['fulfillment']))?></td><td><?php foreach(orderItems((int)$o['id']) as $i): if(pendingQty($i)>0): ?><small><?=e($i['product_name'])?> <?=weight($i['weight_g'])?> × <?=pendingQty($i)?></small><?php endif;endforeach ?></td></tr><?php endforeach ?></tbody></table></div><?php if(!$orders): ?><p>이 기간에 전달 대기 중인 주문이 없습니다.</p><?php endif ?></section>
<section class="panel"><details><summary>소매점 납품 추가량 입력 (선택 · 제품 완성 중량 kg)</summary><div class="form-grid minor-action"><?php foreach(productionRecipes()['retail'] as $key=>$r): ?><label><?=e($r['name'])?> (kg)<input type="number" name="retail[<?=$key?>]" value="<?=e(is_string($retail[$key]??null)?$retail[$key]:'0')?>" min="0" max="99999.999" step="0.001"></label><?php endforeach ?></div><p class="hint">개인 주문과 배합 기준이 다른 제품은 엑셀의 ‘마트판매’ 기준으로 계산합니다. 판매 주문이나 매출은 만들지 않습니다.</p></details><button class="button large minor-action">재료 소요량 계산</button></section></form>
<?php if($calculated): ?><section class="panel"><h2>계산 결과 · 선택 주문 <?=count($picked)?>건</h2><div class="stats three"><?php foreach(['cabbage'=>'배추','radish'=>'무'] as $key=>$label): ?><article><p><?=$label?> 소요량<?=$result['missing'][$key]?' · 계산 가능한 부분':''?></p><strong><?=productionKg($result['totals'][$key])?></strong><span><?=$result['missing'][$key]?'미확인 제품 '.$result['missing'][$key].'종 별도':'선택한 제품 기준'?></span></article><?php endforeach ?></div><?php if(array_sum($result['missing'])): ?><div class="alert error">배합값 또는 용량이 없는 제품이 있습니다. 위 합계는 전체 구매량이 아닙니다. 아래 ‘기준 확인 필요’ 항목의 재료는 별도로 확인해야 합니다.</div><?php endif ?><div class="table-wrap"><table><thead><tr><th>제품</th><th>대기 수량</th><th>완성 중량</th><th>배추</th><th>무</th></tr></thead><tbody><?php foreach($result['groups'] as $g): ?><tr><td><?=e($g['name'])?></td><td><?=$g['quantity']===null?'소매점 입력':$g['quantity'].'개'?></td><td><?=$g['unknown_weight']?'용량 미확인':productionKg((float)$g['product_g'])?></td><td><?=productionKg($g['cabbage'])?></td><td><?=productionKg($g['radish'])?></td></tr><?php endforeach ?></tbody></table></div><p class="hint">표시는 1g 단위로 올림합니다. 배추 손실률·무 보정은 엑셀 수식을 반영했습니다. 소금·양념은 이번 계산에 포함하지 않습니다. 동치미는 엑셀의 과거 3kg 대신 현재 제품 용량 3.2kg을 사용합니다.</p><details><summary>적용한 엑셀 배합 근거 보기</summary><?php foreach($result['groups'] as $g): ?><p><strong><?=e($g['name'])?></strong> · <?=e($g['recipe']['source']??'엑셀에 확인된 배합 기준이 없습니다.')?></p><?php endforeach ?></details></section><?php endif ?>
